-- Lot 109 : commandes canoniques 201 a 225 sur 433.
--
-- Rapprochement par external_ref. Une commande deja en base garde son
-- identifiant technique, donc ses favoris, son historique de copie, ses
-- visuels et son rangement actuel.
--
-- Quinze commandes changent de nom ici : leur mission s'elargit et le
-- classeur leur donne un nom plus juste (/emailpro devient /messagepro).
-- L'adresse publique, elle, ne bouge pas : le slug n'est jamais reecrit, donc
-- un lien deja partage continue de repondre.

drop table if exists lot_v5_commandes;
create temporary table lot_v5_commandes as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-260","command":"/skinretouch","slug":"skinretouch","family_id":"IMG-V5-03","title":"Retouche peau naturelle","short_description":"Retouchez la peau en conservant pores et identité.","main_use_case":"Un portrait nécessite une finition beauté discrète.","level":"A","preset_key":"blemishremove","required_variables":["image","personne"],"optional_variables":["niveau","zones","format"],"sufficient_context":"Sujet identifiable et transformation non ambiguë; textes et données critiques disponibles si nécessaires.","blocking_condition":"Sujet absent ou inexploitable; donnée exacte indispensable non fournie; contradiction qui rendrait le résultat trompeur.","default_values":"Style : portrait naturel et flatteur; ratio : 4:5; haute définition; choix créatifs secondaires décidés automatiquement.","preserve":"Conserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.","avoid":"Évite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique.","output_format":"Image finale, ratio par défaut 4:5, haute définition; prompt final de repli si moteur image indisponible.","risk_level":"moyen","mode":"image","input_type":"image","output_type":"image","max_questions":null,"questionnaire_mode":"successif","aliases":["blemishremove","skinretouch","Retouches localisées"]},{"ref":"RCI-IMG-267","command":"/textremove","slug":"textremove","family_id":"IMG-V5-05","title":"Retirer un texte","short_description":"Retirez un texte ciblé et reconstruisez son support.","main_use_case":"Une affiche personnelle doit être réutilisée sans son ancien titre.","level":"B","preset_key":"textremove","required_variables":["image","zone_texte"],"optional_variables":["éléments_à_garder","format"],"sufficient_context":"Sujet identifiable et transformation non ambiguë; textes et données critiques dispo